 id(target+'-revalidate').onclick=()=>run(id(target+'-revalidate'),async()=>{node.querySelectorAll('[data-p2-note]').forEach(input=>{rows[Number(input.dataset.p2Note)].duplicate_note=input.value;});preview=await api2('import/preview',{activity_id:activity,rows});renderPreview(target,activity,rows);},id(target+'-error'));
